import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Getter
public enum SlayerTaskStreak {
    Off("Off"),
    Ten("10"),
    Fifty("50");

    private final String value;

    SlayerTaskStreak(String value) {
        this.value = value;
    }

    public void logDebug() {
        log.debug("SlayerTaskStreak - name: {}, value: {}", this.name(), this.value);
    }
}

