	private final String DEBUG_MENU_RESET_WORLD_POINTS = "Reset WorldPoints (Mazchna Skipping)";
	private final String DEBUG_MENU_COPY_TO_CLIPBOARD = "Copy WorldPoints to clipboard (Mazchna Skipping)";

